"""Build source-linked industry/system context from the executable pack catalog."""
import json
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from app.design_studio.knowledge.provider import LocalKnowledgeProvider

ROOT=Path(__file__).resolve().parents[1]
INDUSTRIES=[('agriculture','Agriculture and food production'),('mining','Mining and extraction'),('manufacturing','Manufacturing and machinery'),('energy','Energy and utilities'),('water_waste','Water, waste and environmental services'),('construction','Construction and engineering'),('wholesale_retail','Wholesale, retail and spare parts'),('transport','Transport and logistics'),('hospitality','Hospitality and travel'),('technology','Software and IT services'),('communications','Communications and media'),('finance_insurance','Financial and insurance services'),('property','Real estate and property'),('professional','Professional and business services'),('administration','Administrative and support services'),('public_sector','Public administration'),('education','Education and training'),('healthcare','Healthcare administration'),('arts_recreation','Arts and recreation'),('personal_services','Personal and community services'),('other','Other or mixed industry')]
MAPPING={'cat_transport':['transport'],'cat_warehouse':['transport','wholesale_retail','manufacturing'],'cat_manufacturing':['manufacturing'],'cat_ecommerce':['wholesale_retail'],'cat_inventory':['wholesale_retail','manufacturing','agriculture'],'cat_procurement':['construction','manufacturing','public_sector'],'cat_aftersales':['manufacturing','personal_services'],'cat_crm':['professional','wholesale_retail'],'cat_finance':['finance_insurance','professional'],'cat_workforce':['administration'],'cat_healthcare_admin':['healthcare'],'cat_education_services':['education'],'cat_hospitality_booking':['hospitality'],'cat_construction_delivery':['construction'],'cat_property_operations':['property'],'cat_agriculture_operations':['agriculture'],'cat_public_service_requests':['public_sector'],'cat_it_service_management':['technology']}
VARIANTS={'cat_transport':[('own_fleet','Own fleet','Plan vehicle and driver availability before dispatch.'),('outsourced_carrier','Outsourced carrier','Assign the carrier and map its tracking events; do not assume a carrier API.'),('cross_border','Cross-border delivery','Record origin/destination jurisdictions; document and customs requirements need a sourced country-specific policy.')], 'cat_procurement':[('direct','Direct purchasing','Plan material demand and supplier delivery with production.'),('indirect','Indirect purchasing','Route departmental requests for review and purchase.')], 'cat_inventory':[('single_site','Single-site stock','Record stock movement and count adjustments at one location.'),('multi_site','Multi-site stock','Record source/destination locations and transfer receipt.')], 'cat_workforce':[('office','Office teams','Use the shared task process and customer-approved role ownership.'),('shift','Shift-based operations','Propose shift coverage information; working-time rules require customer policy.')], 'cat_ecommerce':[('b2b','Business customers','Capture customer purchase references and customer-selected payment terms.'),('b2c','Consumer orders','Propose customer contact and fulfilment steps; country-specific terms require review.')]}


def build():
 provider=LocalKnowledgeProvider(); systems=[]
 for pack in provider.packs():
  if pack.usage!='blueprint' or not pack.workflows or pack.company: continue
  domains=[d for d in provider.domains() if d.id==pack.domain_id]
  systems.append({'id':pack.id,'name':pack.title,'domain_id':pack.domain_id,'blueprint_id':pack.id,'blueprint_version':pack.version,'industry_ids':MAPPING.get(pack.id,[]),'keywords':domains[0].keywords if domains else [pack.title.lower()],
   'processes':[{'workflow_id':w.id,'name':w.name,'activities':[{'id':s.id,'name':s.label,'role_id':s.role_id,'reads':s.reads_entity_ids,'writes':s.writes_entity_ids,'rules':s.rule_ids,'exception_ids':s.exception_ids} for s in w.states]} for w in pack.workflows],
   'variants':[{'id':k,'name':n,'design_guidance':v,'status':'proposed_pattern'} for k,n,v in VARIANTS.get(pack.id,[('standard','Standard operational workflow','Use the reusable workflow and retain customer-specific changes as project knowledge.')])],
   'status':'proposed_blueprint','source':{'kind':'authored_pattern','reference':f'knowledge/packs/{pack.id}.json','verification':'needs_review'},'regions':['global','eu','india']})
 return {'version':'2026.10.19.2','note':'Extensible starting coverage, not an exhaustive catalog of every industry, vendor or statutory process. Industry labels are Studio categories, not an official NACE/NIC code crosswalk.',
  'industries':[{'id':k,'name':n} for k,n in INDUSTRIES], 'regions':[
   {'id':'global','name':'Global / decide later','guidance':['Use the shared operational process. Do not infer country, currency, tax, employment or retention policy.'],'sources':[]},
   {'id':'eu','name':'European Union','guidance':['Identify the member state before adding country-specific statutory rules.','Use NACE as a source for industry classification, not an executable business workflow.','VAT identification and invoice requirements need the applicable country and transaction context; do not insert a universal VAT rate.'], 'sources':[{'title':'Eurostat NACE overview','url':'https://ec.europa.eu/eurostat/web/nace/','checked_on':'2026-10-19','scope':'Industry classification reference; not a workflow approval.'},{'title':'European Commission VAT identification numbers','url':'https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-identification-numbers_en','checked_on':'2026-10-19','scope':'VAT identification reference; no tax calculation or threshold is encoded.'}]},
   {'id':'india','name':'India','guidance':['Identify the state and operating context before adding country-specific statutory rules.','Use NIC as a source for industry classification; Studio industry categories are not official NIC mappings.','GST and electronic-invoice integrations require customer applicability review and current official rules; no tax rate or turnover threshold is assumed.'],'sources':[{'title':'MoSPI NIC 2008 code finder','url':'https://www.mospi.gov.in/nic-2008-codefinder','checked_on':'2026-10-19','scope':'Classification source link; detailed classifications need source review.'},{'title':'GST e-Invoice portal','url':'https://einvoice.gst.gov.in/','checked_on':None,'scope':'Official portal reference; automated retrieval returned 403, rules not ingested.'}]}], 'systems':sorted(systems,key=lambda s:s['name'])}

if __name__=='__main__':
 path=ROOT/'app/design_studio/knowledge/system_context.json'; doc=build();path.write_text(json.dumps(doc,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print('Built',len(doc['systems']),'system profiles and',len(doc['industries']),'industry categories')
